def winsorizar_iqr(serie: pd.Series, factor: float = 1.5) -> pd.Series:
    q1 = serie.quantile(0.25)
    q3 = serie.quantile(0.75)
    iqr = q3 - q1
    return serie.clip(lower=q1 - factor * iqr, upper=q3 + factor * iqr)

