def extraer_paginas(sesion: requests.Session, base_url: str, token: str) -> list[dict]:
    registros: list[dict] = []
    cursor: str | None = None
    headers = {"Authorization": f"Bearer {token}"}

    while True:
        params = {"limit": 100}
        if cursor:
            params["cursor"] = cursor
        resp = sesion.get(base_url, headers=headers, params=params, timeout=(5, 30))
        resp.raise_for_status()
        data = resp.json()
        registros.extend(data.get("items", []))
        cursor = data.get("next_cursor")
        if not cursor:
            break
    return registros

