import pandas as pd

def calcular_ticket_promedio(df: pd.DataFrame) -> float:
    if df.empty:
        return 0.0
    pedidos = df["pedido_id"].nunique()
    if pedidos == 0:
        return 0.0
    return float(df["monto_neto"].sum() / pedidos)

