def tasa_retencion(base_ids: set[str], retenidos_ids: set[str]) -> float:
    if not base_ids:
        return 0.0
    validos = base_ids.intersection(retenidos_ids)
    return round(len(validos) * 100.0 / len(base_ids), 2)

