import math

def ic_proporcion_wald(exitos: int, n: int, z: float = 1.96) -> tuple[float, float, float]:
    p = exitos / n
    se = math.sqrt(p * (1 - p) / n)
    return round(p, 4), round(max(0.0, p - z * se), 4), round(min(1.0, p + z * se), 4)

import numpy as np

def bootstrap_ic_mediana(datos: np.ndarray, n_rep: int = 2000, seed: int = 42) -> tuple[float, float]:
    rng = np.random.default_rng(seed)
    n = len(datos)
    medianas = np.empty(n_rep)
    for i in range(n_rep):
        muestra = rng.choice(datos, size=n, replace=True)
        medianas[i] = np.median(muestra)
    return float(np.percentile(medianas, 2.5)), float(np.percentile(medianas, 97.5))

