import math

def ic_wilson(exitos: int, n: int, z: float = 1.96) -> tuple[float, float]:
    if n == 0:
        return (0.0, 0.0)
    p = exitos / n
    denom = 1 + z**2 / n
    centro = (p + z**2 / (2 * n)) / denom
    margen = (z * math.sqrt((p * (1 - p) + z**2 / (4 * n)) / n)) / denom
    return round(centro - margen, 4), round(centro + margen, 4)

